package heimdall_test

import (
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"

	"github.com/aarush323/heimdall-fixture-pay/internal/app"
)

// TestPartialRefundsCannotExceedPayment sends two refunds of 60 on a payment of 100 and wants 422 on the second.
func TestPartialRefundsCannotExceedPayment(t *testing.T) {
	srv := httptest.NewServer(app.New(app.Config{}))
	defer srv.Close()

	post := func(key, body string) int {
		t.Helper()
		req, err := http.NewRequest(http.MethodPost, srv.URL+"/refunds", strings.NewReader(body))
		if err != nil {
			t.Fatal(err)
		}
		req.Header.Set("X-Merchant-ID", "m-1")
		req.Header.Set("Idempotency-Key", key)
		resp, err := srv.Client().Do(req)
		if err != nil {
			t.Fatal(err)
		}
		defer resp.Body.Close()
		return resp.StatusCode
	}

	if got := post("k1", `{"payment_id": "pay_1", "amount": 60}`); got != http.StatusCreated {
		t.Fatalf("first refund of 60 = %d, want 201", got)
	}
	if got := post("k2", `{"payment_id": "pay_1", "amount": 60}`); got != http.StatusUnprocessableEntity {
		t.Fatalf("second refund of 60 on a payment of 100 = %d, want 422: the refunds now total 120", got)
	}
}
